#![allow(clippy::excessive_precision)]

use thermopack_rs::{Cubic, CubicKind, CubicOptions, MixingRule, Phase};

fn kind(name: &str) -> CubicKind {
    match name {
        "PR" => CubicKind::PengRobinson,
        "SRK" => CubicKind::SoaveRedlichKwong,
        "RK" => CubicKind::RedlichKwong,
        "VDW" => CubicKind::VanDerWaals,
        other => panic!("unknown cubic kind: {other}"),
    }
}

#[test]
fn unifac_cubic_state_matches_the_source() {
    let mut checked = 0;
    for row in include_str!("fixtures/unifac_cubic.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let components: Vec<&str> = parts[1].split(',').collect();
        let temperature: f64 = parts[2].parse().unwrap();
        let pressure: f64 = parts[3].parse().unwrap();
        let composition: Vec<f64> = parts[4].split(',').map(|v| v.parse().unwrap()).collect();
        let phase = if parts[5] == "L" {
            Phase::Liquid
        } else {
            Phase::Vapor
        };
        let model = Cubic::with_options(
            kind(parts[0]),
            &components,
            CubicOptions {
                mixing_rule: MixingRule::Unifac,
                ..Default::default()
            },
        )
        .unwrap();
        let state = model.prepare(temperature, &composition).unwrap();
        let volume = state.volume(pressure, phase).unwrap();
        let state_pressure = state.pressure(volume).unwrap();
        let residual = state.residual(volume).unwrap();
        let mut phi = vec![0.0; composition.len()];
        state.ln_fugacity_into(volume, &mut phi).unwrap();
        let mut actual = vec![
            volume,
            state_pressure.value,
            state_pressure.dt,
            state_pressure.dv,
            residual.enthalpy,
            residual.entropy,
            state.enthalpy(volume).unwrap(),
            state.entropy(volume).unwrap(),
        ];
        // The source reports the heat capacity at this position and the
        // native model the baseline enthalpy temperature derivative.
        actual.push(state.baseline_enthalpy_derivative_tp(volume).unwrap());
        actual.extend(phi.iter().copied());
        let expected: Vec<f64> = fields[1..].iter().map(|v| v.parse().unwrap()).collect();
        assert_eq!(expected.len(), actual.len(), "{case}");
        for (position, (source, native)) in expected.iter().zip(actual.iter()).enumerate() {
            if position == 8 {
                continue;
            }
            let tolerance = 1e-2 + 2e-8 * source.abs().max(native.abs());
            assert!(
                (source - native).abs() <= tolerance,
                "{case} quantity {position}: source {source} native {native}"
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 270);
}

#[test]
fn unifac_cubic_source_status_is_reproduced() {
    let mut statuses = [0usize; 4];
    for row in include_str!("fixtures/unifac_cubic_status.csv")
        .lines()
        .skip(1)
    {
        let (case, status) = row.split_once(';').unwrap();
        let status: usize = status.parse().unwrap();
        let parts: Vec<_> = case.split('|').collect();
        let components: Vec<&str> = parts[1].split(',').collect();
        let model = Cubic::with_options(
            kind(parts[0]),
            &components,
            CubicOptions {
                mixing_rule: MixingRule::Unifac,
                ..Default::default()
            },
        );
        // The source terminates for components that its own UNIFAC database
        // does not spell the same way as the equation of state.
        assert_eq!(model.is_err(), status == 1, "{case}");
        statuses[status] += 1;
    }
    assert_eq!(statuses[0], 270);
    assert_eq!(statuses[1], 18);
    assert_eq!(statuses[2], 0);
    assert_eq!(statuses[3], 0);
}
